import { useState, useEffect } from 'react';
import { BrowserRouter, Routes, Route, Link, useNavigate, useParams } from 'react-router-dom';
import axios from 'axios';

function getUserId() {
    const [userId, setUserId] = useState(0);
    const [loading, setLoading] = useState(true);

    useEffect(() => {
        const fetchUserId = async () => {
            try {
                const response = await axios.get('/api/user_id');
                setUserId(response.data.user_id);
            } catch (err) {
                console.error('Error:', err);
                setUserId(0);
            } finally {
                setLoading(false);
            }
        };

        fetchUserId();
    }, []);

    return { userId, loading };
}


function NavigationButton({ path, title }) {
    const navigate = useNavigate();

    const handleClick = () => {
        navigate(path);
    };

    return (
        <button 
            className="Navigation-button"
            onClick={handleClick}
        >
            {title}
        </button>
    );
}

function LoginButton({ path, title }) {
    const navigate = useNavigate();

    const handleClick = () => {
        window.location.href = `https://skilled-gazelle-wildly.ngrok-free.app${path}`;
    }

    return (
        <button 
            className="Navigation-button"
            onClick={handleClick}
        >
            {title}
        </button>
    );
}

export function Home() {
    const {user_id, loading} = getUserId();

    if(loading) {
        return <div className="Button-holder">...Loading</div>;
    }

    return (
        <div className="Button-holder">
            <NavigationButton
            title="Play"
            path="/hub"
            />

            { user_id > 0 ?
                (
                    <NavigationButton
                    title="View Profile"
                    color="#1a9c2a"
                    path="/profile"
                    />
                ) : (
                    <NavigationButton
                    title="Login"
                    color="#1a9c2a"
                    path="/login"
                    />
                )
            }


            <NavigationButton
            title="Leaderboard"
            color="#1a9c2a"
            path="/leaderboard"
            />

            <NavigationButton
            title="About"
            color="#aa3c3a"
            path="/about"
            />
        </div>
    )

}

export function Hub() {
    return (
        <div className="Button-holder">
            <NavigationButton
            title="Normal 180s"
            path="/play?game_mode=0"
            />

            <NavigationButton
            title="Normal 300s"
            path="/play?game_mode=1"
            />

            <NavigationButton
            title="Normal 600s"
            path="/play?game_mode=2"
            />
        </div>
    );
}

export function Login() {
    return (
        <div className="Button-holder">
            <LoginButton
            title="Login With Google"
            path="/api/auth/google"
            />

            <LoginButton
            title="Login With GitHub"
            path="/api/auth/github"
            />
        </div>
    );
}

export function Profile() {
    // const { user_id } = useParams();
    // 
    // const [userProfile, setUserProfile] = useState(null);

    return (
        <>
            <h1>Profile</h1>
        </>
    );
}

export function Leaderboard() {
    return <h1>Leaderboard</h1>
}

export function About() {
    return <h1>About</h1>
}
